import{z as i,x as B,o as t,c as d,q as o,j as n,D as r,d as E,s as l,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"贪心正确性","description":"","frontmatter":{"title":"贪心正确性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/greedy-correct.md","filePath":"cs/greedy-correct.md","lastUpdated":1791413859000}'),p={name:"cs/greedy-correct.md"};function D(c,a,m,f,h,u){const s=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="贪心正确性" tabindex="-1">贪心正确性 <a class="header-anchor" href="#贪心正确性" aria-label="Permalink to &quot;贪心正确性&quot;">​</a></h1><div class="epigraph"><p>局部最优要能接到某个全局最优上：要么交换论证补成最优，要么最优子结构允许先做这一步。</p><footer>—— 据 CLRS 第 16 章；活动选择与 Huffman 的标准论证整理</footer></div><p>上一课<a href="/cs/aho-corasick">Aho–Corasick</a>是线性扫描，不是逐步选「当前最便宜」。此前 MST、Dijkstra 已经用过贪心，但没有单独说<strong>何时允许</strong>。本课不重跑 Kruskal。缺口是：把「每步取看起来最好的」写成可证的模板——<strong>贪心选择性质</strong> + <strong>最优子结构</strong>——并标明失败的典型样子。后课动态规划处理贪心不够时的重叠子问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>活动选择：不重叠区间里最多选几个。按结束时间最早贪心，交换论证：任何最优解若第一步不同，可换成这个最早结束而不减个数。Huffman：权最小的两棵树合并，类似。缺口不是再给一个具体算法，而是承认：<strong>贪心不是定义，是要证的性质</strong>。没有证明，反例（找零在某些币制、背包按密度）会静默错。</p><p><span class="marginnote">术语翻译：交换论证就是把「你贪心选的那步」与「某个最优解里对应的那步」互换，然后证明换完之后解没有变差——于是贪心的选择也能拼出一个最优解。它是把直觉变成定理的标准手法。</span></p><p><span class="marginnote">数字实例：币制 {1, 3, 4} 找 6 元。「先拿最大」的贪心拿 4+1+1，共 3 枚；最优是 3+3，只要 2 枚。这就是「贪心未证不可用」的最小反例——换个币制，常识规则就静默出错。</span></p><p>Dijkstra/MST 已是安全边或钉死距离；本课把同一类论证叫出来，供后课对照 DP。</p><h3 id="贪心不是「快」的别名" tabindex="-1">贪心不是「快」的别名 <a class="header-anchor" href="#贪心不是「快」的别名" aria-label="Permalink to &quot;贪心不是「快」的别名&quot;">​</a></h3><p>有的贪心很慢，有的 DP 很快。对错与渐近无关。分数背包按密度贪心对；0-1 背包不对——那是<a href="/cs/knapsack">背包</a>的缺口，本课先把「密度看起来好」列为未证明就不可用。</p><p><span class="marginnote">CLRS 第 16 章用活动选择当第一份交换论证。Matroid 给出一类自动正确的贪心，本课点名不展开公理。Huffman 1952 是编码树实例。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写清候选的局部规则。证明：存在最优解包含这一步（或可改造成包含）。剩余子问题同型，归纳。失败时给最小反例，改走 DP 或别的。</p>',13)),(t(),n(A,null,{default:r(()=>[l(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20RULE%5B%22%E5%B1%80%E9%83%A8%E8%A7%84%E5%88%99%22%5D%20--%3E%20EX%5B%22%E4%BA%A4%E6%8D%A2%E6%88%96%E5%88%87%E5%88%86%EF%BC%9A%E6%8E%A5%E5%88%B0%E6%9F%90%E6%9C%80%E4%BC%98%22%5D%0A%20%20EX%20--%3E%20SUB%5B%22%E5%AD%90%E9%97%AE%E9%A2%98%E5%90%8C%E5%9E%8B%22%5D%0A%20%20SUB%20--%3E%20IND%5B%22%E5%BD%92%E7%BA%B3%E5%BE%97%E5%85%A8%E5%B1%80%22%5D%0A%20%20RULE%20--%3E%20FAIL%5B%22%E6%8E%A5%E4%B8%8D%E4%B8%8A%20%E2%86%92%20%E4%B8%8D%E8%B4%AA%E5%BF%83%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/loop-invariant"},"循环不变式"),E("仍可用：已选集合始终可扩展成最优。那是同一证明的迭代写法。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("安全边、最早结束、Extract-Min 都是本模板的实例。后课 DP 也要最优子结构，但"),e("strong",null,"多分支都要算"),E("：因为不知道哪条局部选择对。贪心是「证明只需走一条」。")],-1)),(t(),n(A,null,{default:r(()=>[l(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E5%AD%90%E9%97%AE%E9%A2%98%22%5D%20--%3E%20G%5B%22%E8%B4%AA%E5%BF%83%EF%BC%9A%E6%80%A7%E8%B4%A8%E5%B7%B2%E8%AF%81%22%5D%0A%20%20G%20--%3E%20G1%5B%22%E5%8F%AA%E7%AE%97%E6%9C%80%E4%BC%98%E7%9A%84%E9%82%A3%E6%9D%A1%E5%88%86%E6%94%AF%22%5D%0A%20%20G1%20--%3E%20GA%5B%22%E4%B8%80%E6%9D%A1%E8%B7%AF%E8%B5%B0%E5%88%B0%E5%BA%95%22%5D%0A%20%20Q%20--%3E%20D%5B%22DP%EF%BC%9A%E6%80%A7%E8%B4%A8%E6%9C%AA%E8%AF%81%20%2F%20%E5%A4%9A%E8%A7%A3%E5%B9%B6%E5%AD%98%22%5D%0A%20%20D%20--%3E%20D1%5B%22%E6%9E%9A%E4%B8%BE%E6%89%80%E6%9C%89%E5%88%86%E6%94%AF%E5%8F%96%E6%9C%80%E4%BC%98%22%5D%0A%20%20D1%20--%3E%20DA%5B%22%E7%8A%B6%E6%80%81%E9%97%B4%E9%80%92%E6%8E%A8%E5%A1%AB%E8%A1%A8%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p>Huffman 树、活动选择留在 P。后面的 NPC 课不要把「旅行商最近邻」当贪心成功案例。</p><p><span class="marginnote">直觉类比：贪心像已有地图确认「这条岔路必通终点」，只走这一条；DP 像没有地图，每个岔口都派一名探子把所有支路走一遍再比较。所以贪心通常更快，但前提是那张「地图」（贪心选择性质）真的被证明过。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入拟阵证明。不写近似比（贪心近似是另一层）。0-1 背包、最短超串等失败例只点到，完整 DP 在下一课。也不把 Dijkstra 再证一遍。</p><p>后课默认：先问贪心选择是否可证；不能证就不要实现成贪心。重叠子问题与备忘是动态规划的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>贪心正确 = 贪心选择性质 + 最优子结构，需证。</li><li>交换论证把局部接到某全局最优。</li><li>密度、最近邻等未证则不可用。</li><li>出处：CLRS 第 16 章；Huffman, 1952。</li></ul>',7))])}const g=i(p,[["render",D]]);export{_ as __pageData,g as default};
